var d=MobileGame.Foundation.Editor.GameDataAssets.LoadCatalog();
var codec=new MobileGame.Persistence.SessionSnapshotCodec(d.Definitions.Values,true);
var root=MobileGame.Foundation.Editor.Plan020Probe.Root;
var result=new System.Collections.Generic.List<object>();
foreach(int level in new[]{0,1,2}) {
 var raw=System.IO.File.ReadAllText(System.IO.Path.Combine(root,"fixture-"+level+".json"));
 var state=codec.Restore(codec.Deserialize(raw));var lab=(MobileGame.Gameplay.LaboratoryManager)state.Runtime;
 void Bench(string name,System.Action op,int n){
 var watch=new System.Diagnostics.Stopwatch();var map=lab.Map;
 var searches=map.PathQueries;var visits=map.VisitedCells;var checks=map.WalkabilityChecks;
 watch.Start();for(int i=0;i<n;i++)op();watch.Stop();
 result.Add(new{level,name,n,ms=watch.Elapsed.TotalMilliseconds,searches=map.PathQueries-searches,visits=map.VisitedCells-visits,checks=map.WalkabilityChecks-checks});
 }
 var w=System.Linq.Enumerable.First(lab.Registry.Things,t=>t.TryGetComponent<MobileGame.Gameplay.WorkerComponent>(out _));
 var f=System.Linq.Enumerable.FirstOrDefault(lab.Registry.Things,t=>t.Definition.Kind==MobileGame.Foundation.ThingKind.Facility);
 Bench("cell-lookup",()=>lab.Map.IsWalkable(new UnityEngine.Vector2Int(15,9)),100000);
 Bench("path",()=>MobileGame.Foundation.GridPathfinder.FindPath(lab.Map,new UnityEngine.Vector2Int(1,1),new UnityEngine.Vector2Int(15,9)),100);
 Bench("advance-16ms",()=>lab.Advance(.016),120);
 Bench("logistics-validity",()=>lab.Logistics.Reconcile(),40);
 if(f!=null)Bench("move",()=>MobileGame.Gameplay.WorkerManager.Move(lab,w,f,.001),20);
}
return result;
